CREATE TABLE `GPCL_MIG_TABLE` (
  `TABLE_ID` varchar(30) NOT NULL COMMENT '테이블ID (PK1, 이관 대상 식별자)',
  `PROC_ORD` decimal(5,0) NOT NULL COMMENT '처리순서',
  `TASK_ID` varchar(30) DEFAULT NULL COMMENT '작업ID',
  `TABLE_NM` varchar(100) NOT NULL,
  `MIG_COND` varchar(4000) DEFAULT NULL COMMENT '이관조건 (WHERE절 본문, 키워드 제외. 공란=전체 추출)',
  `MIG_MODE` char(1) NOT NULL DEFAULT 'A' COMMENT '이행방식. A=설정따름(기본) J=JDBC추출 S=서버사이드추출',
  `LOB_YN` char(1) NOT NULL DEFAULT 'N' COMMENT 'LOB여부. Y=LOB(BLOB/CLOB/LONG) 컬럼 보유 N=일반(기본)',
  `MIG_MODE_RSN` varchar(20) DEFAULT NULL COMMENT '이행방식 지정사유. DELIM/LOB/MANUAL. 기본경로면 NULL',
  `PARALLEL_DGR` decimal(3,0) NOT NULL DEFAULT 1 COMMENT '병렬도 (SPLIT_YN=Y 이면 2 이상 필수, 상한 32)',
  `MNGR_ID` varchar(20) DEFAULT NULL COMMENT '담당자 (DASH-01·MIG-01 조회조건 및 그리드 항목)',
  `BIZ_AREA_CD` varchar(30) DEFAULT NULL COMMENT '업무영역코드 (DW/경영정보/여신IT)',
  `SUBJ_AREA_CD` varchar(30) DEFAULT NULL COMMENT '주제영역코드 (고객/계좌/거래/상품/채널/공통코드)',
  `GRP1_CD` varchar(30) DEFAULT NULL COMMENT '그룹1코드',
  `GRP2_CD` varchar(30) DEFAULT NULL COMMENT '그룹2코드',
  `GRP3_CD` varchar(30) DEFAULT NULL COMMENT '그룹3코드',
  `GRP4_CD` varchar(30) DEFAULT NULL COMMENT '그룹4코드',
  `GRP5_CD` varchar(30) DEFAULT NULL COMMENT '그룹5코드',
  `CLNUP_TP_CD` varchar(10) DEFAULT NULL COMMENT '정리방식코드 (TRUNCATE/DELETE/NONE. NULL=자동판정)',
  `USE_YN` char(1) NOT NULL DEFAULT 'Y' COMMENT '사용여부 (N=이행 대상 제외, 논리 삭제. 배치는 Y만 조회)',
  `REG_ID` varchar(20) DEFAULT NULL COMMENT '등록자',
  `REG_DTM` datetime DEFAULT current_timestamp() COMMENT '등록일시',
  `LST_ADJPRN_ID` varchar(20) DEFAULT NULL COMMENT '최종수정자',
  `LST_ADJ_DTM` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '최종수정일시',
  PRIMARY KEY (`TABLE_ID`,`PROC_ORD`),
  KEY `IX_GPCL_MIG_TABLE_03` (`USE_YN`,`TASK_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='이관 대상 Property - 이관 대상 테이블의 조회조건 메타(업무영역·주제영역·그룹1~5)·이관조건·처리순서·분할설정·정리방식·사용여부 관리';

